import{_ as t,a,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Red Hat Enterprise Linux 6.5 系统管理","description":"面向 RHEL 6.5 历史环境的系统管理导读，关注账户、存储、服务与恢复。","frontmatter":{"title":"Red Hat Enterprise Linux 6.5 系统管理","description":"面向 RHEL 6.5 历史环境的系统管理导读，关注账户、存储、服务与恢复。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 网络与操作系统","summary":"面向 RHEL 6.5 历史环境的系统管理导读，关注账户、存储、服务与恢复。","status":"active","related":[{"title":"计算机网络基础教程（第3版）","link":"/life/personal/books/computing/network-foundations","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络简介实验手册","link":"/life/personal/books/computing/network-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络互连技术","link":"/life/personal/books/computing/internetworking","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络技术教程","link":"/life/personal/books/computing/network-technology","kind":"书籍导读","scope":"general","audience":"general"},{"title":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"计算机网络原理","link":"/life/personal/books/computing/network-principles","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Linux命令行与shell脚本编程大全（第4版）","link":"/life/personal/books/computing/linux-shell","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"计算机网络原理","link":"/life/personal/books/computing/network-principles"},"next":{"text":"Linux命令行与shell脚本编程大全（第4版）","link":"/life/personal/books/computing/linux-shell"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"计算机网络原理","link":"/life/personal/books/computing/network-principles"},"next":{"text":"Linux命令行与shell脚本编程大全（第4版）","link":"/life/personal/books/computing/linux-shell"}},"headers":[],"relativePath":"life/personal/books/computing/rhel-65.md","filePath":"life/personal/books/computing/rhel-65.md"}'),i={name:"life/personal/books/computing/rhel-65.md"};function o(l,e,s,d,p,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="red-hat-enterprise-linux-6-5-系统管理" tabindex="-1">Red Hat Enterprise Linux 6.5 系统管理 <a class="header-anchor" href="#red-hat-enterprise-linux-6-5-系统管理" aria-label="Permalink to &quot;Red Hat Enterprise Linux 6.5 系统管理&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 网络与操作系统</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书的阅读方向是 Linux 系统管理：从安装和账户管理进入存储、进程、服务与网络配置，适合需要理解传统企业 Linux 运维方式的读者，也可用于认识旧系统的配置与排障路径。</p><p>阅读时应关注配置保存在哪里、服务怎样启动、权限如何判定、日志如何记录。将这些机制串起来，才能解释“文件已经修改，为什么运行行为仍然没有变化”。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>图书版本待确认，系统目标为书名所示的 RHEL 6.5。</strong> 尚无作者、出版社和 ISBN，以下为本站主题导读，不是原书目录。RHEL 6 的启动与服务管理方式和较新发行版存在差异，不能把新版本命令直接当作本书操作步骤。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>实物作者仍待版权页核对。当前找到的同名书目候选为马玉军、陈连山编著、清华大学出版社2014年版，ISBN 9787302376880；本次尚未获得该书出版社原始页面，故不据书商记录直接确认藏书或作者履历。Red Hat 是目标系统提供方，不应被写成本书作者；系统官方文档只能核验操作原理。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合需要理解或维护 RHEL 6 系列旧环境、研究传统企业 Linux 管理方式的读者。首次学习 Linux 且没有旧环境需求的人，应优先用受支持系统练习，再回看本书中的历史工具与配置方法。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>阅读与实验关注点</th></tr></thead><tbody><tr><td>安装与启动</td><td>认识分区、引导过程和运行级别，记录系统启动时各阶段的责任。</td></tr><tr><td>文件与权限</td><td>区分所有者、用户组、普通权限和特殊权限，验证实际访问身份。</td></tr><tr><td>用户与认证</td><td>管理账户生命周期，理解本地身份、认证策略和权限委派。</td></tr><tr><td>软件包管理</td><td>通过 RPM 与 Yum 理解依赖、软件来源和升级记录。</td></tr><tr><td>进程与服务</td><td>关联进程、启动脚本和服务状态，区分配置文件与已加载配置。</td></tr><tr><td>存储与文件系统</td><td>学习挂载、逻辑卷和容量监测，明确扩容、卸载与恢复的前置条件。</td></tr><tr><td>网络与访问控制</td><td>检查接口、解析与防火墙规则，同时理解 SELinux 对访问行为的影响。</td></tr><tr><td>日志、计划任务与备份</td><td>形成可追溯的维护过程，使用恢复验证检查备份是否真正可用。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>配置文件改过了，仍要证明运行状态已经改变。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>在隔离虚拟机中为一项服务记录配置文件、启动方式、运行身份、监听端口和日志入口，重启后验证状态，再演练恢复。这个过程能训练从文件变化追到进程行为，而不是把命令退出成功当作维护完成。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>旧系统资料对定位遗留环境很有用，但软件源、管理命令和安全默认值具有年代限制。不能将书中网络服务直接作为新生产环境模板；应先确认系统支持边界，并在隔离环境中练习恢复和迁移。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给面对旧系统、需要先理解再迁移的人：带着服务状态与恢复路径阅读，旧知识才有明确用途。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名与 RHEL 6.5 目标版本来自本次书单；原书目录待版权页核对。</li><li><a href="https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/6" target="_blank" rel="noopener noreferrer">Red Hat Enterprise Linux 6 官方文档</a>：对应系统世代的管理文档入口，不是本书目录。</li><li><a href="https://access.redhat.com/support/policy/updates/errata" target="_blank" rel="noopener noreferrer">RHEL 生命周期政策</a>：判断旧版本支持范围的官方入口。</li><li><a href="https://www.megbook.com.hk/mall/detail.jsp?proID=2467116" target="_blank" rel="noopener noreferrer">同名候选书目</a>：仅辅助比对作者、2014年版与 ISBN；未代替出版社或实物确认。</li></ul>',26)])])}const k=t(i,[["render",o]]);export{u as __pageData,k as default};
